<?php

namespace App\Support;

use App\Models\SiteContent;
use Illuminate\Database\QueryException;
use Illuminate\Support\Facades\File;
use RuntimeException;

/**
 * Site data for the public website: the JSON generated by SchoolForge
 * (resources/school/site.json) with content edited in the admin panel applied on top.
 */
class SchoolSite
{
    /** SiteContent key for page settings edited under Admin → Website. */
    public const PAGE_SETTINGS = '_pages';

    /** SiteContent key for brand colours edited under Admin → Website. */
    public const DESIGN = '_design';

    /**
     * Site data per language, after admin edits.
     *
     * @var array<string, array<string, mixed>>
     */
    private array $data = [];

    public function __construct(private readonly string $path) {}

    /**
     * Site data for a language (default language when null), with admin edits applied.
     *
     * @return array{school: array<string, mixed>, content: array<string, mixed>, theme: array<string, mixed>, navigation: list<array{label: string, href: string}>, layout: array<string, mixed>, pages: list<array{slug: string, title: string, description?: string, sections: list<array<string, mixed>>}>, i18n?: array<string, mixed>}
     */
    public function data(?string $locale = null): array
    {
        $locale = $locale !== null && in_array($locale, $this->locales(), true) ? $locale : $this->defaultLocale();

        return $this->data[$locale] ??= $locale === $this->defaultLocale() ? $this->defaultData() : $this->translatedData($locale);
    }

    public function defaultLocale(): string
    {
        return $this->fileData()['i18n']['defaultLocale'] ?? 'en';
    }

    /**
     * @return list<string>
     */
    public function locales(): array
    {
        return array_column($this->fileData()['i18n']['locales'] ?? [], 'code') ?: [$this->defaultLocale()];
    }

    /**
     * What a translated section looks like before admin translation edits: the
     * default-language value with the translation from school.config.json laid over it.
     */
    public function translationBase(string $locale, string $key): mixed
    {
        return TranslationMerger::merge(
            ContentSchema::valueFrom($this->data(), $key),
            ContentSchema::valueFrom($this->translations()[$locale] ?? [], $key, configShape: true),
        );
    }

    /**
     * @return array<string, mixed>
     */
    private function defaultData(): array
    {
        $site = $this->fileData();

        foreach ($this->overrides() as $key => $value) {
            if (ContentSchema::find($key) !== null) {
                $site = ContentSchema::apply($site, $key, $value);
            }
        }

        return $this->withPageSettings($this->withGeneratedPages($site), true);
    }

    /**
     * @return array<string, mixed>
     */
    private function translatedData(string $locale): array
    {
        $site = $this->fileData($locale);
        $overrides = $this->overrides();

        foreach (array_keys(ContentSchema::sections()) as $key) {
            $value = TranslationMerger::merge($this->translationBase($locale, $key), $overrides["{$locale}:{$key}"] ?? null);
            $site = ContentSchema::apply($site, $key, $value);
        }

        return $this->withPageSettings($this->withGeneratedPages($site), false);
    }

    /**
     * Page titles, menu labels, descriptions, menu visibility and order set under
     * Admin → Website. Wording applies to the default language; visibility and
     * order to every language. The menu is rebuilt from the pages when they change.
     *
     * @param  array<string, mixed>  $site
     * @return array<string, mixed>
     */
    private function withPageSettings(array $site, bool $isDefaultLanguage): array
    {
        $settings = $this->overrides()[self::PAGE_SETTINGS] ?? [];

        if ($settings === []) {
            return $site;
        }

        $pages = array_map(function (array $page) use ($settings, $isDefaultLanguage): array {
            $setting = $settings[$page['slug']] ?? [];
            $wording = $isDefaultLanguage ? array_filter(array_intersect_key($setting, array_flip(['title', 'navLabel', 'description'])), fn ($value): bool => filled($value)) : [];

            return [...$page, ...$wording, ...(isset($setting['showInNav']) ? ['showInNav' => (bool) $setting['showInNav']] : [])];
        }, $site['pages']);

        $position = fn (array $page): int => $settings[$page['slug']]['order'] ?? PHP_INT_MAX;
        usort($pages, fn (array $a, array $b): int => $position($a) <=> $position($b));

        $site['pages'] = $pages;
        $site['navigation'] = array_values(array_map(
            fn (array $page): array => ['label' => $page['navLabel'] ?? $page['title'], 'href' => $page['slug']],
            array_filter($pages, fn (array $page): bool => ($page['showInNav'] ?? false) && ! str_starts_with($page['slug'], '/news/') && ! str_starts_with($page['slug'], '/gallery/')),
        ));

        return $site;
    }

    /**
     * CSS that applies brand colours chosen under Admin → Website on top of the
     * generated theme, with readable text colours worked out for each.
     */
    public function colorOverridesCss(): string
    {
        $colors = array_filter($this->overrides()[self::DESIGN]['colors'] ?? [], fn ($value): bool => is_string($value) && preg_match('/^#[0-9a-f]{6}$/i', $value));

        if ($colors === []) {
            return '';
        }

        $variables = [];

        foreach ($colors as $name => $hex) {
            $variables["--color-{$name}"] = $hex;
            $variables["--color-{$name}-foreground"] = Color::readableOn($hex);
        }

        if (isset($colors['accent'])) {
            $variables['--color-accent-strong'] = Color::darkenUntilReadable($colors['accent'], '#ffffff', 4.5);
        }

        return ':root{'.collect($variables)->map(fn (string $value, string $name): string => "{$name}:{$value}")->implode(';').'}';
    }

    /**
     * The generated site data (for a language) without admin edits.
     *
     * @return array<string, mixed>
     */
    public function fileData(?string $locale = null): array
    {
        $path = $locale === null ? $this->path : dirname($this->path)."/site.{$locale}.json";

        if (! File::exists($path)) {
            if ($locale !== null) {
                return $this->fileData();
            }

            throw new RuntimeException("School site data not found at [{$this->path}]. Run `schoolforge sync` in the project root.");
        }

        return json_decode(File::get($path), true, flags: JSON_THROW_ON_ERROR);
    }

    /**
     * Translations from school.config.json (config shape), keyed by language.
     *
     * @return array<string, array<string, mixed>>
     */
    public function translations(): array
    {
        $path = dirname($this->path).'/translations.json';

        return File::exists($path) ? json_decode(File::get($path), true, flags: JSON_THROW_ON_ERROR) : [];
    }

    /**
     * Forget cached data so the next read picks up new admin edits.
     */
    public function refresh(): void
    {
        $this->data = [];
    }

    /**
     * @return array{slug: string, title: string, description?: string, sections: list<array<string, mixed>>}|null
     */
    public function findPage(string $slug, ?string $locale = null): ?array
    {
        foreach ($this->data($locale)['pages'] as $page) {
            if ($page['slug'] === $slug) {
                return $page;
            }
        }

        return null;
    }

    /**
     * The live site address: `seo.siteUrl` from the school config, or APP_URL.
     */
    public function siteUrl(): string
    {
        return rtrim($this->data()['seo']['siteUrl'] ?? url('/'), '/');
    }

    public function schoolName(): string
    {
        return (string) $this->data()['school']['name'];
    }

    /**
     * @return list<string>
     */
    public function fontStylesheets(): array
    {
        return $this->data()['theme']['fontImports'] ?? [];
    }

    /**
     * @return array<string, mixed>
     */
    private function overrides(): array
    {
        try {
            return SiteContent::query()->pluck('value', 'key')->all();
        } catch (QueryException) {
            return [];
        }
    }

    /**
     * Rebuilds the per-article news pages and per-album gallery pages, so stories
     * and albums added in the admin panel get their own URL.
     *
     * @param  array<string, mixed>  $site
     * @return array<string, mixed>
     */
    private function withGeneratedPages(array $site): array
    {
        $pages = array_values(array_filter(
            $site['pages'],
            fn (array $page): bool => ! collect($page['sections'])->contains(fn (array $section): bool => in_array($section['type'], ['article', 'album'], true)),
        ));
        $slugs = array_column($pages, 'slug');

        foreach ($site['content']['news'] ?? [] as $article) {
            $slug = '/news/'.$article['slug'];

            if (! empty($article['body']) && ! in_array($slug, $slugs, true)) {
                $pages[] = array_filter([
                    'slug' => $slug,
                    'title' => $article['title'],
                    'description' => $article['excerpt'] ?? null,
                    'showInNav' => false,
                    'sections' => [['type' => 'article', 'newsSlug' => $article['slug']]],
                ], fn ($value): bool => $value !== null);
                $slugs[] = $slug;
            }
        }

        foreach ($site['content']['albums'] ?? [] as $album) {
            $slug = '/gallery/'.$album['slug'];

            if (! in_array($slug, $slugs, true)) {
                $pages[] = array_filter([
                    'slug' => $slug,
                    'title' => $album['title'],
                    'description' => $album['description'] ?? null,
                    'showInNav' => false,
                    'sections' => [['type' => 'album', 'albumSlug' => $album['slug']]],
                ], fn ($value): bool => $value !== null);
                $slugs[] = $slug;
            }
        }

        $site['pages'] = $pages;

        return $site;
    }
}
